#include <iostream>
using namespace std;

template <typename T1, typename T2>
T2 calculerMoyenne(T1 tableau[], int taille) {
    T2 somme = 0;
    for (int i = 0; i < taille; ++i)
        somme += tableau[i];
    return somme / taille;
}

int main() {
    int n;
    cin >> n;
    int tab[100];
    for (int i = 0; i < n; ++i)
        cin >> tab[i];
    cout << calculerMoyenne<int, double>(tab, n) << "\n";
    return 0;
}

