solution.referenceCode:
#include <iostream>
using namespace std;

template <typename T>
class Pile {
    T elements[100];
    int sommet;
public:
    Pile() : sommet(0) {}
    void empiler(const T& x) { elements[sommet++] = x; }
    void depiler() { --sommet; }
    T haut() const { return elements[sommet - 1]; }
    bool vide() const { return sommet == 0; }
};

int main() {
    int n;
    cin >> n;
    Pile<int> p;
    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        p.empiler(x);
    }
    cout << p.haut() << "\n";
    p.depiler();
    cout << p.haut() << "\n";
    cout << (p.vide() ? "vide" : "non vide") << "\n";
    return 0;
}
